// Tiny assert-and-count harness shared by the driver's standalone unit tests
// (cli_test, json_test, and F5+ infra tests). No doctest dependency: each test
// is its own executable, calls CHECK(...) for each assertion, and ends with
// `return andes_sim::test::report("<name>");`.
#ifndef ANDESIM_TEST_CHECK_HPP
#define ANDESIM_TEST_CHECK_HPP

#include <cstdio>
#include <string>
#include <vector>

namespace andes_sim::test {

inline int g_failures = 0;

inline int report(const char* what) {
  if (g_failures) {
    std::fprintf(stderr, "%d check(s) failed\n", g_failures);
    return 1;
  }
  std::printf("all %s checks passed\n", what);
  return 0;
}

}  // namespace andes_sim::test

#define CHECK(cond)                                                        \
  do {                                                                     \
    if (!(cond)) {                                                         \
      std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
      ++andes_sim::test::g_failures;                                       \
    }                                                                      \
  } while (0)

namespace andes_sim::test {

// Element-wise compare two string vectors: CHECK the size, then each element,
// printing got/want on the first mismatch. `label` tags the diff line. Shared
// by the driver's argv-shaped unit tests (plan_test, run_test). Defined after
// CHECK so the macro is in scope.
inline void check_eq(const std::vector<std::string>& got,
                     const std::vector<std::string>& want, const char* label) {
  CHECK(got.size() == want.size());
  const size_t n = got.size() < want.size() ? got.size() : want.size();
  for (size_t i = 0; i < n; ++i) {
    if (got[i] != want[i])
      std::fprintf(stderr, "  %s[%zu]: got '%s' want '%s'\n", label, i,
                   got[i].c_str(), want[i].c_str());
    CHECK(got[i] == want[i]);
  }
}

}  // namespace andes_sim::test

#endif  // ANDESIM_TEST_CHECK_HPP

// ELF symbol resolution for pc-trigger boundaries (F9).
//
// pc mode switches QEMU <-> vsim at two PCs. Either boundary may be a
// "0x"-prefixed hex address (used verbatim) OR a symbol defined in the ELF
// (resolved against its .symtab). This decouples the switch points from the
// workload source -- any function can bound the ROI, with no planted markers.
//
// C++ port of tests/lib/roi.sh:resolve_pc, reading the ELF .symtab directly via
// <elf.h> rather than shelling out to `nm`.
#ifndef ANDESIM_ELF_SYMS_HPP
#define ANDESIM_ELF_SYMS_HPP

#include <cstdint>
#include <string>

namespace andes_sim {

// Resolve a pc-mode boundary to a bare hex address string (no "0x" prefix).
//   "0x<h>" / "0X<h>"  -> "<h>" verbatim (prefix stripped, digits unchanged)
//   <symbol>           -> the symbol's st_value as lowercase hex
// On any failure (undefined symbol, unreadable/!ELF file) returns "" and sets
// `err` to a message naming the boundary; on success leaves `err` empty.
std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
                       std::string& err);

// The ELF class width in bits from e_ident[EI_CLASS]: 32 (ELFCLASS32) or 64
// (ELFCLASS64). Returns 0 when `elf_path` is unreadable or not an ELF. Reads
// only the 16-byte e_ident (the class-independent prefix), so it answers for
// rv32 and rv64 alike -- the source of truth for the fast auto-pick of
// qemu-system-riscv32/64 and the cycle/hybrid arch-match guard.
int elf_xlen(const std::string& elf_path);

// L26/F3: the highest byte of the ELF's static memory image -- the maximum
// (p_paddr + p_memsz) over PT_LOAD segments. The driver rejects a hybrid run
// when this exceeds the V-scratch GPA (ram_base + --mem-size): the static image
// would extend into the reserved transport page above the program's RAM.
// Returns 0 + err on an unreadable / non-ELFCLASS64 file; 0 with empty err when
// the ELF has no loadable segments (nothing to clash with the scratch).
uint64_t elf_load_top(const std::string& elf_path, std::string& err);

// Reverse lookup: the nearest function symbol at or below `addr`, formatted
// "name+0xoff" (or just "name" at offset 0). Returns "" when no covering
// function symbol is found or the ELF is unreadable -- the caller always has
// the raw pc to fall back on, so this never errors.
std::string symbolize(const std::string& elf_path, uint64_t addr);

// Returns {st_value, st_value + st_size} for the FUNC symbol covering `addr`.
// Both members are 0 when not found or unreadable.
std::pair<uint64_t, uint64_t> fn_range(const std::string& elf_path, uint64_t addr);

}  // namespace andes_sim

#endif  // ANDESIM_ELF_SYMS_HPP

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <functional>
#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// is redirected to /dev/null; stderr too, unless relay_stderr is set, in
// which case the child inherits OUR stderr and its diagnostics stream live
// (used to surface the legs' leveled logs at --log-level <= debug). If the
// child runs longer than timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms,
                      bool relay_stderr = false);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

// Fork a child that execs argv with inherited stdio and return immediately
// without waiting. Used by `run --mode cycle --gdb` to launch vsim in the
// background before exec-ing ICEman in the foreground. Returns the child pid
// on success, -1 on empty argv or fork failure.
