  test_parse_plugin_log();
  test_parse_disasm();
  test_is_rvv();
  test_ranges();
  test_filter_loops();
  test_build_loops_nesting();
  test_measure_ret_pc();
  test_src_helpers();
  test_render_llm();
  test_render_table();
  test_profile_qemu_argv();
  return andes_sim::test::report("profile");
}

