1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <algorithm>
12	#include <chrono>
13	#include <cstdint>
14	#include <cstdio>
15	#include <cstdlib>
16	#include <filesystem>
17	#include <optional>
18	#include <string>
19	#include <string_view>
20	#include <thread>
21	#include <vector>
22	
23	#include "argv.hpp"
24	#include "cli.hpp"
25	#include "elf_syms.hpp"
26	#include "engine_descriptor.hpp"
27	#include "engine_registry.hpp"
28	#include "hybrid.hpp"
29	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F3 overlap check)
30	#include "log.hpp"
31	#include "memmap.hpp"
32	#include "models.hpp"
33	#include "plan.hpp"
34	#include "process.hpp"
35	#include "repo_root.hpp"
36	#include "run_passthrough.hpp"
37	#include "run_plan.hpp"
38	#include "shm.hpp"
39	#include "state.hpp"
40	#include "state_diff.hpp"
41	#include "vsim_filter.hpp"
42	
43	namespace fs = std::filesystem;
44	
45	namespace andes_sim {
46	namespace {
47	
48	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
49	// success; on failure prints an error tagged with `ctx` and returns "". The
50	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
51	// missing path fails with a clear "ELF not found" instead of being handed to the
52	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
53	// up-front check run_hybrid already does.
54	std::string abs_elf(const std::string& path, const std::string& ctx) {
55	  std::error_code ec;
56	  fs::path abs = fs::absolute(path, ec);
57	  if (ec) {
58	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
59	                 ctx.c_str(), path.c_str());
60	    return "";
61	  }
62	  if (!fs::is_regular_file(abs, ec)) {
63	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
64	                 path.c_str());
65	    return "";
66	  }
67	  return abs.string();
68	}
69	
70	// Validate the lone-ELF positional shape the standalone models require: print
71	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
72	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
73	// spawns a --describe subprocess per Verilator build). `model` labels the error.
74	int check_one_elf(const Cli& cli, const char* model) {
75	  if (cli.positional.empty()) {
76	    std::fprintf(stderr,
77	                 "andesim run --mode %s: missing ELF (the workload to run; "
78	                 "e.g. a tests/fixtures/<name>.elf)\n",
79	                 model);
80	    return 2;
81	  }
82	  if (cli.positional.size() > 1) {
83	    std::fprintf(stderr,
84	                 "andesim run --mode %s: unexpected argument '%s' "
85	                 "(engine args go after --)\n",
86	                 model, cli.positional[1].c_str());
87	    return 2;
88	  }
89	  return 0;
90	}
91	
92	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
93	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
94	// from deep inside the engine. Both directions. Returns "" when they agree, when
95	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
96	// declares no xlen (cannot judge). Shared by cycle and hybrid: one wording.
97	std::string elf_engine_arch_error(const std::string& elf,
98	                                  const EngineDescriptor& eng) {
99	  const int ex = elf_xlen(elf);
100	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
101	  char buf[256];
102	  std::snprintf(buf, sizeof(buf),
103	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
104	                "or an rv%d ELF",
105	                ex, eng.id.c_str(), eng.xlen, ex);
106	  return buf;
107	}
108	
109	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
110	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
111	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
112	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
113	// reports the plan, it does not run it.
114	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
115	                  const std::vector<std::string>& labels) {
116	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
117	  for (size_t i = 0; i < argvs.size(); ++i) {
118	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
119	                labels[i].c_str());
120	    std::printf("%s\n", render_argv(argvs[i]).c_str());
121	  }
122	  return 0;
123	}
124	
125	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
126	// and verbose [info] log (VsimFilter), relaying only the program's own output
127	// and any real diagnostics, then restate the lifted cycle count as andesim's own
128	// one-line result under the [andesim] prefix. The count is printed AFTER the run
129	// (the engine logs it at exit), so it follows the program output. Returns the
130	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
131	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
132	int run_cycle_clean(const std::vector<std::string>& argv) {
133	  VsimFilter filter;
134	  const int rc = run_line_filtered(
135	      argv, [&filter](int stream, std::string_view line) {
136	        std::FILE* dst = nullptr;
137	        switch (filter.classify(stream, line)) {
138	          case VsimFilter::Dest::kStdout: dst = stdout; break;
139	          case VsimFilter::Dest::kStderr: dst = stderr; break;
140	          case VsimFilter::Dest::kDrop: return;
141	        }
142	        std::fwrite(line.data(), 1, line.size(), dst);
143	        std::fputc('\n', dst);
144	      });
145	  if (const std::optional<uint64_t> c = filter.cycles())
146	    log_result(kLogInfo, "[andesim] %llu cycles",
147	               static_cast<unsigned long long>(*c));
148	  return rc;
149	}
150	
151	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
152	// then run the resolved engine standalone with `extra` (model flags the
153	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
154	// `clean_output` picks how the engine's output is presented: fast inherits the
155	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
156	// semihosting console works unchanged); cycle filters out the engine's banner +
157	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
158	// exit code propagates. The per-model engine + selection are resolved by the
159	// caller; `model` here only labels the positional diagnostics.
160	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
161	                   const char* model, const std::vector<std::string>& extra = {},
162	                   bool clean_output = false) {
163	  if (int rc = check_one_elf(cli, model)) return rc;
164	  // QEMU's -bios flag searches its data directory for relative paths rather
165	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
166	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
167	  if (elf.empty()) return 2;
168	  std::vector<std::string> args = extra;
169	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
170	  std::string err;
171	  const std::vector<std::string> argv =
172	      passthrough_argv(eng, "standalone", elf, args, err);
173	  if (!err.empty()) {
174	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
175	    return 2;
176	  }
177	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
178	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
179	  if (cli.dry_run)
180	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
181	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
182	  // wedged engine still leaves the exact command in the log.
183	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
184	           render_argv(argv).c_str());
185	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
186	}
187	
188	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
189	// only the built-in qemu descriptor, so it resolves that directly rather than
190	// discover_engines(), which would spawn a --describe subprocess per Verilator
191	// build only to discard them all here.
192	int run_fast(const Cli& cli) {
193	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
194	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
195	    std::fprintf(stderr,
196	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
197	                 "got '%s'\n",
198	                 cli.engine.c_str());
199	    return 2;
200	  }
201	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
202	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
203	  std::string err;
204	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
205	  if (!err.empty()) {
206	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
207	    return 2;
208	  }
209	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
210	  if (cli.gdb) {
211	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
212	    extra.push_back("-gdb");
213	    extra.push_back("tcp::" + port);
214	    extra.push_back("-S");
215	  }
216	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
217	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
218	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
219	  // ELF -- the override is the user's call.
220	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
221	  int xlen;
222	  if (cli.engine == kQemuId32) xlen = 32;
223	  else if (cli.engine == kQemuId64) xlen = 64;
224	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
225	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
226	  // == elf_w), so this guard already implies an explicit --engine.
227	  if (elf_w && elf_w != xlen)
228	    std::fprintf(stderr,
229	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
230	                 "(running as rv%d)\n",
231	                 cli.engine.c_str(), xlen, elf_w, xlen);
232	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
233	}
