// Resolve a per-host setting the way setup.sh and the test harness do: the
// environment wins, else the first `KEY=value` assignment in the gitignored
// per-host config.env. This lets `./andesim` find the external qemu/vsim
// (QEMU_BIN_DIR / VSIM_BIN_DIR) without a prior `source ./setup.sh`, matching
// how cmd_doctor already resolves HYBRID_TOOLCHAIN.
#ifndef ANDESIM_CONFIG_ENV_HPP
#define ANDESIM_CONFIG_ENV_HPP

#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <string>
#include <string_view>

#include "repo_root.hpp"

namespace andes_sim {

// $key (non-empty) wins; else the first `key=value` line in `config_file`
// (leading whitespace and `# comment` lines ignored). Empty string if neither
// yields a value; a missing config file is not an error.
inline std::string config_env_value(std::string_view key,
                                    const std::filesystem::path& config_file) {
  const std::string k{key};
  if (const char* e = std::getenv(k.c_str()); e && *e) return e;

  std::ifstream f(config_file);
  if (!f) return "";
  const std::string prefix = k + "=";
  std::string line;
  while (std::getline(f, line)) {
    const std::size_t b = line.find_first_not_of(" \t");
    if (b == std::string::npos || line[b] == '#') continue;
    if (line.compare(b, prefix.size(), prefix) != 0) continue;
    std::string val = line.substr(b + prefix.size());
    val.erase(val.find_last_not_of(" \t\r") + 1);  // right-trim (npos+1 == 0)
    return val;
  }
  return "";
}

// Same, against the repo's own config.env.
inline std::string config_env_value(std::string_view key) {
  return config_env_value(key, repo_root() / "config.env");
}

}  // namespace andes_sim

#endif  // ANDESIM_CONFIG_ENV_HPP

// andesim leveled logging.
//
// The scale mirrors the vsim engines' --log-level option so users learn one
// scheme: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off. A message
// prints when its level >= the threshold; the default threshold is info.
//
// What lives at which level (driver policy):
//   info  -- the answers: program output relays, the cycle figure,
//            --dry-run/--verify results. Program output itself is never
//            gated (it is the program's, not a log).
//   debug -- driver chatter: the hybrid banner, the mmap line, PASS lines,
//            verify progress notes.
//   warn  -- degradations: unsupported-CSR warnings, skipped engines.
// Fatal errors are not gated: they accompany a non-zero exit.
#ifndef ANDESIM_LOG_HPP
#define ANDESIM_LOG_HPP

#include <string>

namespace andes_sim {

enum LogLevel {
  kLogTrace = 0,
  kLogDebug = 1,
  kLogInfo = 2,
  kLogWarn = 3,
  kLogError = 4,
  kLogCritical = 5,
  kLogOff = 6,
};

// Set the process-wide threshold from the CLI value. "" keeps the default
// (info). Returns false (and leaves the threshold alone) when the value is
// not an integer in 0..6.
bool set_log_threshold(const std::string& cli_value);

// The current threshold (0..6). Used to forward the level to child engines.
int log_threshold();

// True when a message at `level` should print.
bool log_on(int level);

// Open the --log-file sink. Once open, EVERY log_line/log_result message --
// all levels, even below the console threshold -- is appended to the file
// with a UTC timestamp and a level tag. Returns false if the file cannot be
// opened (the sink stays off). Empty path is a no-op success.
bool set_log_file(const std::string& path);

// The open sink's path, or "" when none.
const std::string& log_file_path();

// Emit one chatter line to stderr when `level` passes the threshold. Pass
// the complete line text (including its "[andesim] " prefix), without the
// trailing newline. Always mirrored to the --log-file sink.
void log_line(int level, const char* fmt, ...)
    __attribute__((format(printf, 2, 3)));

// Emit one RESULT line (the cycle figure, PASS/verify verdicts) to stdout
// when `level` passes the threshold. Always mirrored to the sink.
void log_result(int level, const char* fmt, ...)
    __attribute__((format(printf, 2, 3)));

}  // namespace andes_sim

#endif  // ANDESIM_LOG_HPP

input.content:
// `andesim profile [--engine <id>] [report flags] ELF [-- <qemu args>]`.
//
// Hot inner-loop detection on the FUNCTIONAL engine, configured like the
// hybrid fast leg: profile picks a cycle-accurate engine (--engine or the
// sole one, the same selector cycle/hybrid use) and derives the QEMU launch
// from it -- the CPU model from the engine's `--print-qemu-config` driver
// globals, vlen from its --describe, and the staged qemu.cfg as -readconfig.
// That keeps the profiled ISA identical to the engine the reported
// `measure: --pc-start/--pc-end` windows will be measured on (a wrong vlen
// changes vsetvl trip counts, i.e. the hot-loop ranking itself).
//
// QEMU runs the ELF to completion with the hotloops TCG plugin; the plugin's
// `-d plugin -D` log is parsed, filtered (min-iters, RVV-only), nested, and
// rendered as the LLM Markdown report (or --no-llm table). All pure logic
// lives in profile.cpp; this file owns the IO: engine resolve, the cfg probe,
// the QEMU spawn, objdump/addr2line, and the per-loop symbol lookups.
#include <unistd.h>

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include "argv.hpp"
#include "cli.hpp"
#include "config_env.hpp"
#include "elf_syms.hpp"
#include "engine_descriptor.hpp"
#include "engine_registry.hpp"
#include "log.hpp"
#include "process.hpp"
#include "profile.hpp"
#include "repo_root.hpp"
#include "run_plan.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// The bundled hot-loop plugin under the repo root (the profile counterpart of
// default_plugin_path's hybrid plugin).
fs::path profile_plugin_path() {
  return repo_root() / "qemu_plugin" / "libhotloops.so";
}

// Does `cmd` resolve to an executable (absolute/relative path, or via PATH)?
bool cmd_exists(const std::string& cmd) {
  if (cmd.find('/') != std::string::npos)
    return ::access(cmd.c_str(), X_OK) == 0;
  const char* path_env = std::getenv("PATH");
  if (!path_env) return false;
  std::istringstream ss(path_env);
  std::string dir;
  while (std::getline(ss, dir, ':'))
    if (!dir.empty() && ::access((dir + "/" + cmd).c_str(), X_OK) == 0)
      return true;
  return false;
}

std::string find_first(const std::vector<std::string>& cands) {
  for (const auto& c : cands)
    if (cmd_exists(c)) return c;
  return "";
}

// The cross objdump chain: --objdump wins, else $HYBRID_TOOLCHAIN (env or
// config.env) so RISC-V vendor extensions (RVV, Andes custom) decode
// correctly -- generic llvm-objdump on old distros may not know RVV.
std::string resolve_objdump(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  std::vector<std::string> cands;
  if (const std::string tc = config_env_value("HYBRID_TOOLCHAIN"); !tc.empty()) {
    cands.push_back(tc + "/bin/riscv64-unknown-elf-objdump");
    cands.push_back(tc + "/bin/riscv32-unknown-elf-objdump");
  }
  cands.insert(cands.end(), {"riscv64-unknown-elf-objdump",
                             "riscv32-unknown-elf-objdump", "llvm-objdump",
                             "objdump"});
  return find_first(cands);
}

// Write lines to argv's stdin; capture its stdout. Used for addr2line, which
// takes one hex address per input line.
std::string capture_with_stdin(const std::vector<std::string>& argv,
                               const std::string& input) {
  if (argv.empty()) return "";
  int in_fds[2], out_fds[2];
  if (pipe(in_fds) != 0) return "";
  if (pipe(out_fds) != 0) {
    close(in_fds[0]);
    close(in_fds[1]);
    return "";
  }
  pid_t pid = fork();
  if (pid < 0) {
    close(in_fds[0]); close(in_fds[1]);
    close(out_fds[0]); close(out_fds[1]);
    return "";
  }
  if (pid == 0) {
    close(in_fds[1]);
    close(out_fds[0]);
    dup2(in_fds[0], STDIN_FILENO);
    dup2(out_fds[1], STDOUT_FILENO);
    if (FILE* devnull = std::fopen("/dev/null", "w"))
      dup2(fileno(devnull), STDERR_FILENO);
    close(in_fds[0]);
    close(out_fds[1]);
    std::vector<char*> cargv;
    cargv.reserve(argv.size() + 1);
    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
    cargv.push_back(nullptr);
    execvp(cargv[0], cargv.data());
    _exit(127);
  }
  close(in_fds[0]);
  close(out_fds[1]);
  const char* p = input.data();
  size_t rem = input.size();
  while (rem > 0) {
    ssize_t w = write(in_fds[1], p, rem);
    if (w < 0) break;
    p += w;
    rem -= static_cast<size_t>(w);
  }
  close(in_fds[1]);
  std::string out;
  char buf[4096];
  ssize_t n;
  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
    out.append(buf, static_cast<size_t>(n));
  close(out_fds[0]);
  int status = 0;
  waitpid(pid, &status, 0);
  return out;
}

// addr2line every pc in `pcs` against `elf_path`; unknown ("??") lines drop
// out, so absent keys mean "no source info".
std::map<uint64_t, std::string> resolve_sources(
    const std::string& addr2line_bin, const std::string& elf_path,
    const std::vector<uint64_t>& pcs) {
  std::map<uint64_t, std::string> result;
  if (addr2line_bin.empty() || pcs.empty()) return result;
  std::string input;
  for (uint64_t pc : pcs) {
    char buf[20];
    std::snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
    input += buf;
  }
  const std::string out =
      capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
  std::istringstream ss(out);
  std::string line;
  size_t idx = 0;
  while (std::getline(ss, line) && idx < pcs.size()) {
    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
      line.pop_back();
    if (!line.empty() && line.find("??") == std::string::npos)
      result[pcs[idx]] = line;
    ++idx;
  }
  return result;
}

// The trimmed text of `path`'s line `lineno` ("" when unreadable).
std::string read_source_line(const std::string& path, int lineno) {
  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
  std::ifstream f(path);
  std::string line;
  for (int i = 1; std::getline(f, line); ++i) {
    if (i != lineno) continue;
    while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
                             line.back() == ' ' || line.back() == '\t'))
      line.pop_back();
    auto s = line.find_first_not_of(" \t");
    return (s != std::string::npos) ? line.substr(s) : line;
  }
  return "";
